eco_guide <- 
function (var1 = "var1", var2 = "var2", output = c("viewer", "console")) 
{
    output <- match.arg(output)
    v1 <- gsub("\"", "", deparse(substitute(var1)))
    v2 <- gsub("\"", "", deparse(substitute(var2)))
    lignes_guide <- c("# ==============================================================================", paste0("# GUIDE R SERIES TEMPORELLES - AIDE-MEMOIRE SYNTAXIQUE (var1 = ", v1, " | var2 = ", v2, ")"), "# ==============================================================================", "", "library(quantmod); library(readxl); library(urca); library(forecast)", "library(lmtest); library(sandwich); library(tseries); library(FinTS)", "library(moments); library(vars); library(lpirfs); library(exuber); library(tsDyn)", 
        "", "# ------------------------------------------------------------------------------", "# 0. IMPORT, LOG-RENDEMENTS ET GRAPHIQUES (Chapitre 1)", "# ------------------------------------------------------------------------------", paste0("# getSymbols(\"", v1, "\", src = \"FRED\", from = \"1980-01-01\")"), "# d <- read_excel(\"fichier.xlsx\"); d$date <- as.Date(d$date, origin = \"1899-12-30\")", paste0(v1, " <- na.omit(", v1, ")"), paste0(v2, " <- na.omit(", v2, ")"), paste0("l_", v1, " <- log(", 
            v1, ")"), paste0("d_", v1, " <- na.omit(100 * diff(l_", v1, "))   # ou diff(", v1, ") si deja en taux"), paste0("plot(", v1, ", type = \"l\", col = \"blue\", main = \"Evolution de ", v1, "\")"), paste0("ts.plot(cbind(", v1, ", ", v2, "), col = 1:2)"), paste0("acf(", v1, ", lag.max = 24, main = \"FAC ", v1, "\")"), paste0("pacf(", v1, ", lag.max = 24, main = \"FAP ", v1, "\")"), "", "# ------------------------------------------------------------------------------", "# 1. TESTS DE STATIONNARITE : STRATEGIE SEQUENTIELLE ADF & KPSS (Chapitre 2)", 
        "# ------------------------------------------------------------------------------", "# ADF : H0 = Racine unitaire (non stationnaire). Rejet H0 si tau < seuil 5%.", paste0("adf3_", v1, " <- ur.df(", v1, ", type = \"trend\", lags = 8, selectlags = \"AIC\")"), paste0("summary(adf3_", v1, ")"), paste0("adf2_", v1, " <- ur.df(", v1, ", type = \"drift\", lags = 8, selectlags = \"AIC\")"), paste0("summary(adf2_", v1, ")"), paste0("adf1_", v1, " <- ur.df(", v1, ", type = \"none\", lags = 8, selectlags = \"AIC\")"), 
        paste0("summary(adf1_", v1, ")"), "", "# KPSS : H0 = Stationnarite (inverse de ADF). Rejet H0 si stat > seuil 5%.", paste0("kpss_mu_", v1, "  <- ur.kpss(", v1, ", type = \"mu\", lags = \"short\")"), paste0("kpss_tau_", v1, " <- ur.kpss(", v1, ", type = \"tau\", lags = \"long\")"), paste0("summary(kpss_mu_", v1, ")"), paste0("d_", v1, " <- diff(", v1, ")"), paste0("summary(ur.df(d_", v1, ", type = \"drift\", lags = 8, selectlags = \"AIC\"))"), paste0("mod_tend <- lm(", v1, " ~ seq_along(", 
            v1, "))"), "coeftest(mod_tend, vcov. = vcovHAC(mod_tend, type = \"HAC\"))", "", "# ------------------------------------------------------------------------------", "# 2. DETECTION DE BULLES SPECULATIVES EXPLOSIVES : EXUBER (Chapitre 2.3)", "# ------------------------------------------------------------------------------", paste0("psy_minw(", v1, ")"), paste0("radf_", v1, " <- radf(", v1, ", lag = 2)"), paste0("mc_cv <- radf_mc_cv(n = length(", v1, "), nrep = 1000, seed = 145)"), paste0("summary(radf_", 
            v1, ", mc_cv)"), paste0("bulle <- datestamp(radf_", v1, ", cv = mc_cv, min_duration = psy_ds(", v1, "), option = \"gsadf\")"), paste0("autoplot(radf_", v1, ", option = \"gsadf\", cv = mc_cv, min_duration = psy_ds(", v1, "))"), "", "# ------------------------------------------------------------------------------", "# 3. MODELISATION ARMA, DIAGNOSTICS & PREVISION (Chapitre 3)", "# ------------------------------------------------------------------------------", paste0("auto_mod <- auto.arima(", 
            v1, ", max.p = 4, max.q = 4, d = 0, seasonal = FALSE, ic = \"bic\", stepwise = FALSE, approximation = FALSE)"), "summary(auto_mod)", paste0("arma_fit <- Arima(", v1, ", order = c(1, 0, 2))"), "coeftest(arma_fit); autoplot(arma_fit)", "checkresiduals(arma_fit, lag = 10)            # Ljung-Box (H0: bruit blanc, souhaite p > 0.05)", "jarque.bera.test(arma_fit$residuals)          # Normalite (H0: normale)", "skewness(arma_fit$residuals); kurtosis(arma_fit$residuals)", "ArchTest(arma_fit$residuals, lags = 4, demean = FALSE) # Effet ARCH (H0: homoscedastique)", 
        "fc <- forecast(arma_fit, h = 5, level = 95); print(fc); autoplot(fc)", "", "# ------------------------------------------------------------------------------", "# 4. MODELES VAR, GRANGER, IRF & PROJECTIONS LOCALES (Chapitre 4)", "# ------------------------------------------------------------------------------", paste0("Y <- na.omit(cbind(", v1, ", ", v2, "))"), paste0("colnames(Y) <- c(\"", v1, "\", \"", v2, "\")"), "VARselect(Y, lag.max = 8, type = \"const\")", "var_fit <- VAR(Y, p = 3, type = \"const\"); summary(var_fit)", 
        "roots(var_fit)                                                # tous < 1 => VAR stable", "serial.test(var_fit, lags.pt = 10, type = \"PT.adjusted\")      # H0: pas d autocorrelation", "arch.test(var_fit, lags.multi = 4, multivariate.only = TRUE)  # H0: pas d effet ARCH", "normality.test(var_fit, multivariate.only = TRUE)             # H0: normalite", paste0("causality(var_fit, cause = \"", v1, "\")$Granger"), paste0("causality(var_fit, cause = \"", v2, "\")$Granger"), "set.seed(123); irf_fit <- irf(var_fit, n.ahead = 12, ortho = TRUE, ci = 0.90, boot = TRUE); plot(irf_fit)", 
        "plot(fevd(var_fit, n.ahead = 12))", "irf_LP <- lp_lin(endog_data = as.data.frame(Y), lags_endog_lin = 3, trend = 0, shock_type = 0, confint = 1.645, hor = 14, adjust_se = TRUE)", "plot(irf_LP)", "", "# ------------------------------------------------------------------------------", "# 5. COINTEGRATION DE JOHANSEN & VECM (Chapitre 5 - Series I(1) en niveau)", "# ------------------------------------------------------------------------------", paste0("Y_lvl <- na.omit(cbind(", v1, ", ", v2, 
            "))"), "VARselect(Y_lvl, lag.max = 12, type = \"const\")$selection", "jo_trace <- ca.jo(Y_lvl, type = \"trace\", ecdet = \"const\", K = 4, spec = \"transitory\")", "summary(jo_trace)", "vecm_ols <- cajorls(jo_trace, r = 1); summary(vecm_ols$rlm); vecm_ols$beta", "vecm_ml <- VECM(Y_lvl, lag = 3, r = 1, estim = \"ML\", include = \"none\", LRinclude = \"const\"); summary(vecm_ml)")
    script_txt <- paste(lignes_guide, collapse = "\n")
    if (output == "console") {
        cat(script_txt, "\n")
    }
    else {
        html_file <- tempfile(fileext = ".html")
        html_content <- paste0("<!DOCTYPE html><html><head><meta charset='utf-8'>", "<title>Aide-Memoire EcoTS : ", v1, " & ", v2, "</title>", "<style>", "body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; margin: 16px; background: #f8f9fa; color: #212529; }", "h2 { color: #0d6efd; border-bottom: 2px solid #0d6efd; padding-bottom: 6px; font-size: 1.2em; }", "table { border-collapse: collapse; width: 100%; margin-bottom: 16px; font-size: 0.85em; background: #fff; }", 
            "th, td { border: 1px solid #dee2e6; padding: 6px 8px; text-align: left; }", "th { background: #e9ecef; }", "pre { background: #1e1e1e; color: #d4d4d4; padding: 14px; border-radius: 6px; overflow-x: auto; font-size: 0.85em; line-height: 1.45; }", "</style></head><body>", "<h2>Aide-Memoire Econometrie II (<code>", v1, "</code> & <code>", v2, "</code>)</h2>", "<table><tr><th>Test</th><th>Fonction</th><th>H0</th><th>Rejet H0 (5%)</th></tr>", "<tr><td>ADF</td><td><code>ur.df(urca)</code></td><td>Racine unitaire</td><td>t &lt; val. critique</td></tr>", 
            "<tr><td>KPSS</td><td><code>ur.kpss(urca)</code></td><td>Stationnarite</td><td>stat &gt; val. critique</td></tr>", "<tr><td>Bulles</td><td><code>radf(exuber)</code></td><td>Racine unitaire (vs explosive)</td><td>stat &gt; val. critique</td></tr>", "<tr><td>Ljung-Box</td><td><code>checkresiduals</code></td><td>Bruit blanc</td><td>p &lt; 0.05</td></tr>", "<tr><td>Jarque-Bera</td><td><code>jarque.bera.test</code></td><td>Normalite</td><td>p &lt; 0.05</td></tr>", "<tr><td>ARCH-LM</td><td><code>ArchTest(FinTS)</code></td><td>Homoscedasticite</td><td>p &lt; 0.05</td></tr>", 
            "<tr><td>Granger</td><td><code>causality(vars)</code></td><td>Absence de causalite</td><td>p &lt; 0.05</td></tr>", "<tr><td>Johansen</td><td><code>ca.jo(urca)</code></td><td>Rang &le; r</td><td>stat &gt; val. critique</td></tr></table>", "<pre><code>", gsub("<", "&lt;", gsub(">", "&gt;", script_txt)), "</code></pre>", "</body></html>")
        writeLines(html_content, html_file)
        viewer <- getOption("viewer")
        if (!is.null(viewer) && rstudioapi::isAvailable()) {
            viewer(html_file)
        }
        else {
            utils::browseURL(html_file)
        }
    }
    invisible(script_txt)
}
